var type=typeof(EchoSphere.Runtime.EchoSphereRuntime);var source=(EchoSphere.Presentation.V)type.Assembly.GetType("EchoSphere.Presentation.Visual_region",true).GetField("Scope").GetValue(null);var catalog=EchoSphere.Presentation.NativeRunCatalog.Instance;int checks=0;
void Equal(object a,object b,string key){if(!object.Equals(a,b))throw new Exception(key+": "+a+" != "+b);checks++;}
void Pocket(EchoSphere.Presentation.NativeRunCatalog.Pocket row,EchoSphere.Presentation.V original){Equal(row.Id,original["id"].Text,"pocket id");Equal(row.NameRu,original["name"]["ru"].Text,"pocket ru");Equal(row.NameEn,original["name"]["en"].Text,"pocket en");Equal(row.X,original["center"]["x"].Number,"pocket X");Equal(row.Y,original["center"]["y"].Number,"pocket Y");Equal(row.Radius,original["radius"].Number,"radius");Equal(row.Accent,original["accent"].Text,"accent");}
foreach(var region in catalog.Regions){var original=source["getRegionConfig"].Call(region.Id);Equal(region.NameRu,original["name"]["ru"].Text,"region ru");Equal(region.NameEn,original["name"]["en"].Text,"region en");Equal(region.Pockets.Count,(int)original["pockets"]["length"].Number,"pocket count");for(int i=0;i<region.Pockets.Count;i++)Pocket(region.Pockets[i],original["pockets"][i]);}
for(int i=0;i<catalog.WorldPockets.Count;i++)Pocket(catalog.WorldPockets[i],source["REGION_POCKETS"][i]);
foreach(double time in new[]{-1d,0,299.999,300,599.999,600,899.999,900,1499.999,1500,1619.999,1620,double.NaN,double.PositiveInfinity}){int index=(int)type.GetMethod("NativeRegionPhaseIndex",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static).Invoke(null,new object[]{time});var original=source["getRegionPhase"].Call(time);Equal(index,(int)original["id"].Number,"phase index");Equal(catalog.RegionPhases[index].NameRu,original["name"]["ru"].Text,"phase ru");Equal(catalog.RegionPhases[index].NameEn,original["name"]["en"].Text,"phase en");}
Equal(catalog.GetRegion("unknown").Id,source["getRegionConfig"].Call("unknown")["id"].Text,"region fallback");return new {checks};
